# -*- coding: utf-8 -*-
"""Package actual direct-sculpt studies beside the existing local gallery."""
from pathlib import Path
from shutil import copy2
BASE = Path(__file__).resolve().parents[2] / 'art/review/terrain_fidelity/2026-10-16/sculpt_base'
ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / 'art/review/terrain_fidelity/2026-10-16/rock_sculpt'
OUT = ROOT / 'art/review/terrain_fidelity/2026-10-14/courtyard_finish'
for name in ['before_close', 'sculpt1_close', 'sculpt2_close', 'sculpt2_overview', 'sculpt2_reverse', 'sculpt2_carved', 'sculpt2_undo']:
    copy2(SOURCE / f'{name}.png', OUT / f'rock_{name}.png')
for name in ['close', 'overview', 'reverse', 'shore', 'bottom']:
    copy2(BASE / f'base5_{name}.png', OUT / f'base5_{name}.png')
page = '''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>岩体直接塑形 · 功能试作</title><style>body{margin:0;background:#e9e8df;color:#35443e;font:16px/1.7 system-ui,sans-serif}main{max-width:1350px;margin:auto;padding:32px}h1{font-size:32px;font-weight:500}p{max-width:940px;color:#63736a}img{width:100%;display:block;border-radius:8px}select{font:inherit;padding:8px;margin:14px 0}a{color:#526e5a}</style><main><a href="comparison.html">返回默认岛屿候选</a><h1>岩体直接塑形 · 功能试作</h1><p>玩家与预制作者直接修改同一份岩体体积：增岩、削岩、切面，支持撤销、保存和继续编辑。这里没有自动摆放或组合石头。以下均为实际 Godot 场景。</p><p><a href="sculpt_base.html">查看新一轮：直接塑造原有岛体</a></p><p><strong>两组形体尚未采用。</strong>第一组偏软泥，第二组偏宽大岩片；这两组保留为早期叠加试作；新一轮已将原有侧崖与草地转为同一个可塑形表面。默认岛屿没有换成这些试版。</p><label>查看步骤 <select id="view"><option value="before_close">原有岛缘</option><option value="sculpt1_close">第一组 · 外形未采用</option><option value="sculpt2_close" selected>第二组 · 外形未采用</option><option value="sculpt2_carved">同一岩体削改后</option><option value="sculpt2_undo">撤销削改后</option><option value="sculpt2_overview">第二组 · 全岛</option><option value="sculpt2_reverse">第二组 · 反向</option></select></label><img id="image" src="rock_sculpt2_close.png" alt="岩体塑形实景试作"><p>功能检查与美术接受分开：连体网格、跨区接缝、增削、切面、撤销及保存已验证；新一轮另已验证完整鼠标操作和草石整体塑形；目标设备性能尚未验证。</p></main><script>document.querySelector('#view').onchange=e=>document.querySelector('#image').src='rock_'+e.target.value+'.png';</script></html>'''
(OUT / 'rock_sculpt.html').write_text(page)
print(OUT / 'rock_sculpt.html')

base_page = '''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>整岛直接塑形 · 试验</title><style>body{margin:0;background:#e9e8df;color:#35443e;font:16px/1.7 system-ui,sans-serif}main{max-width:1350px;margin:auto;padding:32px}h1{font-size:32px;font-weight:500}p{max-width:940px;color:#63736a}img{width:100%;display:block;border-radius:8px}select{font:inherit;padding:8px;margin:14px 0}a{color:#526e5a}</style><main><a href="comparison.html">默认岛屿候选</a> · <a href="rock_sculpt.html">早期试作</a><h1>原有岛体直接塑形 · 试验</h1><p>原有草地、岩壁与岛底成为连续表面。玩家和预制作者可以用相同的增岩、削岩、切面工具直接修改它，支持撤销与保存。这一轮没有自动组合岩石，也没有在旧崖壁外再叠一层。</p><p><strong>这是功能试验，造型尚未采用。</strong>连续性已改善，岩壁仍过于宽大、圆滑，尚未形成概念图里高低错落的岩面和草石掩映。默认岛屿仍保留原候选。</p><label>实机场景 <select id="view"><option value="close">岛缘近景</option><option value="overview">全岛</option><option value="reverse">反向近景</option><option value="shore">湖岸</option><option value="bottom">岛底</option></select></label><img id="image" src="base5_close.png" alt="Godot 整岛塑形试验"><p>完整鼠标削改、存读档、撤销、网格闭合与薄挑檐支撑已验证；四种地形状态的岸石接触和五种状态的藤蔓接触已检查。大岛编辑速度、任意造型与目标设备性能尚未验收。</p></main><script>document.querySelector('#view').onchange=e=>document.querySelector('#image').src='base5_'+e.target.value+'.png';</script></html>'''
(OUT / 'sculpt_base.html').write_text(base_page, encoding='utf-8')
